import fs from 'node:fs';
import path from 'node:path';
import { ROOT, buildContentBundle, loadContent, serializeContentBundle } from './lib/content.mjs';

const expectedJson = serializeContentBundle(buildContentBundle(loadContent()));
const expectedTypeScript =
  "/* Generated by npm run generate. Do not edit. */\nimport data from './content.json';\nexport default data;\n";

const generatedFiles = [
  ['generated/content.json', expectedJson],
  ['generated/content.ts', expectedTypeScript],
];

const staleFiles = generatedFiles
  .filter(([file, expected]) => {
    try {
      return fs.readFileSync(path.join(ROOT, file), 'utf8') !== expected;
    } catch {
      return true;
    }
  })
  .map(([file]) => file);

if (staleFiles.length > 0) {
  console.error(`Generated content is stale: ${staleFiles.join(', ')}. Run npm run generate.`);
  process.exitCode = 1;
} else {
  console.log('Generated content is deterministic and current.');
}
